    var ADDS = [{"p":"PART 1. 통치 체제 개편·붕당 정치의 전개","q":[{"answer":"O","text":"병자호란이 일어나자 김준룡은 광교산에서 청군과 맞서 싸워 이를 크게 물리치는 승리를 거두었다.","exp":"병자호란 때 남한산성이 포위되자 각지에서 구원군이 북상하였고, 그 가운데 김준룡이 광교산 전투에서 청군을 물리쳤다. 임진왜란 때 동래성을 지킨 송상현, 광해군 때 사르후 전투의 강홍립과 시기·인물을 구분해 기억한다.","src":"한능검 제75회"},{"answer":"X","text":"병자호란이 일어나자 김준룡은 동래성에서 청군과 맞서 싸워 이를 크게 물리치는 승리를 거두었다.","exp":"장소가 틀렸다. 김준룡이 청군을 물리친 곳은 동래성이 아니라 광교산이다. 동래성은 임진왜란 초기 송상현이 왜군에 맞서 항전하다 순절한 곳으로 병자호란과 관련이 없다."}],"tb":[],"wi":["📝 \"김준룡이 동래성에서 청군을 물리쳤다\" → ❌ 광교산 전투이다 (동래성 = 임진왜란 송상현 순절지)"]},{"p":"PART 6. 조선 후기 문화·예술과 종교","q":[{"answer":"O","text":"조선 후기에는 책을 빌려 주는 세책가가 생겨나 춘향전과 같은 한글 소설을 빌려 읽는 부녀자들이 있었다.","exp":"조선 후기에는 상업 발달과 서민 의식 성장으로 세책가에서 한글 소설을 빌려 읽거나 전기수에게 이야기를 듣는 문화가 퍼졌다. 세책가·전기수·판소리·사설시조는 모두 조선 후기 서민 문화이다.","src":"한능검 제75회"},{"answer":"X","text":"세종의 명으로 집현전에서 동국정운을 편찬하던 시기에는 세책가에서 춘향전과 같은 한글 소설을 빌려 읽는 부녀자들이 있었다.","exp":"시기가 틀렸다. 세책가에서 한글 소설을 빌려 읽는 모습은 조선 후기의 서민 문화이다. 세종이 집현전에서 동국정운을 편찬한 것은 조선 전기의 일로 두 사실의 시기가 서로 다르다."}],"tb":[],"wi":[]},{"p":"PART 3. 수취 체제 개편·경제 변화","q":[{"answer":"O","text":"조선 후기에는 상평통보가 널리 유통되고 공인이 활동하였으며, 송상·만상이 대청 무역에 종사하고 덕대가 물주의 자본을 받아 광산을 경영하였다.","exp":"상평통보 유통, 공인의 활동, 송상·만상의 대청 무역, 덕대의 광산 경영은 모두 조선 후기 경제의 모습이다. 반면 부산포·제포·염포의 삼포를 열어 왜관에서 교역한 것은 조선 전기의 일임을 구분한다.","src":"한능검 제75회"},{"answer":"X","text":"조선 후기에는 덕대가 물주의 자본으로 광산을 경영하고 상평통보가 유통되었으며, 부산포·제포·염포의 삼포를 열어 왜관에서 일본과 교역하였다.","exp":"왜관 교역 시기가 틀렸다. 덕대의 광산 경영과 상평통보 유통은 조선 후기가 맞지만, 부산포·제포·염포의 삼포를 열어 왜관에서 일본과 교역한 것은 조선 전기의 일이다."}],"tb":[],"wi":[]},{"p":"PART 4. 사회 변동·신분제 동요·농민 항쟁","q":[{"answer":"O","text":"제주의 거상 김만덕은 정조 때 흉년으로 굶주린 제주 백성을 자신의 재산을 들여 구제하였다.","exp":"김만덕은 상업으로 큰 부를 이룬 제주의 여성 거상으로, 정조 때 큰 흉년이 들자 자신의 재산을 풀어 굶주린 제주 백성을 구제하였다. 조선 후기 상업 발달과 여성의 활동을 보여 주는 사례이다.","src":"한능검 제75회"},{"answer":"X","text":"제주의 거상 김만덕은 정조 때 흉년으로 굶주린 한양의 백성을 자신의 재산을 들여 구제하였다.","exp":"구제 대상이 틀렸다. 김만덕이 재산을 들여 구제한 것은 한양 백성이 아니라 흉년으로 굶주린 제주 백성이다. 인물·시기 서술은 옳다."}],"tb":[],"wi":["📝 \"김만덕이 흉년에 한양 백성을 구제하였다\" → ❌ 제주 백성이다 (정조 때 제주 거상)"]}];
