    var ADDS = [{"p":"PART 1. 통치 체제 개편·붕당 정치의 전개","q":[{"answer":"O","text":"숙종 때 기사환국이 일어나 인현왕후가 폐위되고 서인이 대거 쫓겨난 대신 남인이 권력을 장악하였다.","exp":"숙종은 왕비 교체 등을 계기로 집권 붕당을 통째로 갈아치우는 환국을 여러 차례 단행하였는데, 기사환국(1689)에서는 인현왕후가 폐위되고 서인이 축출되면서 남인이 정권을 잡았다. 반대로 갑술환국에서는 남인이 몰락하고 서인이 재집권한 것과 짝지어 기억한다.","src":"한능검 제74회"},{"answer":"X","text":"숙종 때 갑술환국이 일어나 인현왕후가 폐위되고 서인이 대거 쫓겨난 대신 남인이 권력을 장악하였다.","exp":"환국 이름이 틀렸다. 인현왕후가 폐위되고 남인이 권력을 잡은 것은 기사환국이며, 갑술환국은 반대로 남인이 축출되고 인현왕후가 복위되며 서인이 다시 집권한 사건이다."}],"tb":[],"wi":["📝 \"갑술환국으로 인현왕후가 폐위되고 남인이 집권하였다\" → ❌ 기사환국이다 (갑술환국 = 남인 축출·서인 재집권·인현왕후 복위)"]},{"p":"PART 3. 수취 체제 개편·경제 변화","q":[{"answer":"O","text":"조선 후기 한양에서는 종로의 시전 이외에 이현과 칠패 등지에서 난전이 활발하게 벌어져 사상들의 상업 활동이 크게 늘어났다.","exp":"조선 후기 상품 화폐 경제가 발달하면서 시전이 없던 이현(동대문 부근)·칠패(남대문 부근) 등에서 사상들이 벌이는 난전이 번성하였다. 신해통공으로 육의전을 뺀 시전의 금난전권이 폐지되면서 이러한 사상의 활동은 더욱 활발해졌다.","src":"한능검 제74회"},{"answer":"X","text":"조선 후기 한양에서는 종로의 시전 이외에 벽란도와 칠패 등지에서 난전이 활발하게 벌어져 사상들의 상업 활동이 크게 늘어났다.","exp":"장소가 틀렸다. 한양의 대표적 난전 시장은 이현과 칠패이며, 벽란도는 조선의 한양이 아니라 고려 시대 예성강 하구에 있던 국제 무역항이다."}],"tb":[],"wi":[]},{"p":"PART 6. 조선 후기 문화·예술과 종교","q":[{"answer":"O","text":"순조 때 신유박해로 많은 천주교도가 처형되자, 황사영이 외국 군대를 동원하여 신앙의 자유를 얻으려는 내용의 백서를 작성하려다 발각되었다.","exp":"1801년 신유박해로 이승훈·정약종 등이 처형되고 정약용·정약전 등이 유배되자, 황사영이 청과 서양 세력에 도움을 청하는 백서를 몰래 보내려다 발각되어 박해가 더욱 심해졌다. 황사영 백서는 순조 때 신유박해와 짝지어 기억한다.","src":"한능검 제74회"},{"answer":"X","text":"고종 때 병인박해로 많은 천주교도가 처형되자, 황사영이 외국 군대를 동원하여 신앙의 자유를 얻으려는 내용의 백서를 작성하려다 발각되었다.","exp":"박해 시기가 틀렸다. 황사영 백서 사건은 순조 때 신유박해(1801)와 관련된 일이며, 병인박해는 흥선 대원군 집권기인 고종 때 일어난 천주교 박해로 서로 다른 사건이다."}],"tb":[],"wi":["📝 \"병인박해 때 황사영이 백서를 작성하려다 발각되었다\" → ❌ 순조 때 신유박해이다 (병인박해 = 고종·흥선 대원군 때)"]}];
    for (var ai = 0; ai < ADDS.length; ai++) { insQ(ADDS[ai].p, ADDS[ai].q); insT(ADDS[ai].p, ADDS[ai].tb, ADDS[ai].wi); }
