    var ADDS = [{"p":"PART 1. 통치 체제 개편·붕당 정치의 전개","q":[{"answer":"O","text":"통신사는 에도 막부의 요청으로 일본에 파견된 사절단으로, 국왕의 국서를 전달하고 선진 문물을 전파하였으며 관련 기록물이 유네스코 세계 기록 유산에 등재되었다.","exp":"통신사는 일본 에도 막부의 요청에 따라 조선이 파견한 외교 사절로 문물 교류에 크게 기여하였고 그 기록물이 세계 기록 유산에 등재되었다. 청에 보낸 연행사, 미국에 보낸 보빙사와 파견 대상국을 구분해 기억한다.","src":"한능검 제72회"},{"answer":"X","text":"통신사는 국왕의 국서를 전달하고 선진 문물을 전파한 사절단으로, 관련 기록물이 유네스코 세계 기록 유산에 등재되었으며 미국의 요청으로 파견되어 보빙사라고도 불렸다.","exp":"파견 대상국과 명칭이 틀렸다. 통신사는 일본 에도 막부의 요청으로 일본에 파견된 사절이며, 미국에 보낸 사절은 1883년의 보빙사로 서로 다른 사절단이다."}],"tb":[],"wi":["📝 \"통신사는 청 황제(연행사)/미국(보빙사)의 요청으로 파견되었다\" → ❌ 통신사는 일본 에도 막부의 요청으로 일본에 파견"]},{"p":"PART 1. 통치 체제 개편·붕당 정치의 전개","q":[{"answer":"O","text":"송시열은 효종 사후 자의 대비의 복상 문제를 둘러싼 기해예송에서 1년설인 기년설을 주장하였고, 기축봉사를 올려 명에 대한 의리와 북벌을 강조하였다.","exp":"서인의 영수 송시열은 기해예송에서 기년설(1년설)을 내세웠고 기축봉사를 통해 존명 의리와 북벌론을 주장하였다. 남인이 주장한 3년설과 대비하여 기억한다.","src":"한능검 제72회"},{"answer":"X","text":"송시열은 효종 사후 자의 대비의 복상 문제를 둘러싼 기해예송에서 1년설인 기년설을 주장하였고, 의산문답을 지어 지전설과 무한우주론을 주장하였다.","exp":"인물이 뒤섞여 틀렸다. 기해예송에서 기년설을 주장한 이는 송시열이 맞지만, 의산문답에서 지전설·무한우주론을 편 인물은 홍대용이다."}],"tb":[],"wi":[]},{"p":"PART 3. 수취 체제 개편·경제 변화","q":[{"answer":"O","text":"조선 후기에는 담배와 면화 같은 상품 작물의 재배가 늘고 모내기법이 전국으로 확대되었으며, 보부상이 장시를 오가고 설점수세제에 따라 민간의 광산 개발이 이루어졌다.","exp":"담배·면화 등 상품 작물 재배, 모내기법 확대, 보부상의 장시 활동, 설점수세제에 의한 광산 개발은 모두 조선 후기 경제의 특징이다. 화폐 경제가 발달해 상평통보가 널리 유통된 점도 함께 기억한다.","src":"한능검 제72회"},{"answer":"X","text":"조선 후기에는 담배와 면화 같은 상품 작물의 재배가 늘고 모내기법이 전국으로 확대되었으며, 보부상이 장시를 오가고 최초의 금속 화폐인 건원중보가 주조되어 전국적으로 유통되었다.","exp":"화폐가 틀렸다. 건원중보는 고려 성종 때 주조된 우리나라 최초의 금속 화폐이며, 조선 후기에 전국적으로 유통된 화폐는 상평통보이다. 앞의 상품 작물·모내기·보부상은 모두 조선 후기의 모습이 맞다."}],"tb":[],"wi":["건원중보 = 고려 성종 (최초의 금속 화폐) / 조선 후기 유통 화폐로 나오면 ❌ (조선 후기 = 상평통보)"]}];
