    var ADDS = [{"p":"PART 1. 통치 체제 개편·붕당 정치의 전개","q":[{"answer":"O","text":"조선 후기에는 임진왜란 중 설치된 훈련도감을 시작으로 어영청·총융청·수어청·금위영이 차례로 갖추어져 5군영 체제가 완성되었다.","exp":"훈련도감을 시작으로 어영청·총융청·수어청이 갖추어지고 마지막으로 금위영이 설치되어 5군영 체제가 완성되었다. 총융청은 이괄의 난을 계기로, 금위영은 국왕 호위와 도성 수비를 위해 창설되었다.","src":"한능검 제67회"},{"answer":"X","text":"조선 후기 5군영 가운데 국왕 호위와 도성 수비를 맡은 금위영이 임진왜란 중에 가장 먼저 설치되어 5군영 체제의 출발점이 되었다.","exp":"설치 순서가 틀렸다. 임진왜란 중 가장 먼저 설치된 부대는 훈련도감이며, 금위영은 가장 늦은 숙종 때 국왕 호위·도성 수비를 위해 창설되었다. 국왕 호위·도성 수비라는 기능 자체는 금위영이 맞다."}],"tb":[],"wi":[]},{"p":"PART 3. 수취 체제 개편·경제 변화","q":[{"answer":"O","text":"조선 후기에는 상평통보가 법화로 발행되어 전국적으로 널리 유통되었으며, 동전이 부족해지는 전황이 나타나기도 하였다.","exp":"상평통보는 조선 후기 전국적으로 유통된 법화로, 지주·상인이 동전을 쌓아 두면서 시중에 돈이 마르는 전황이 나타났다. 활구(은병)는 고려 숙종 때의 화폐이므로 시대를 구분해야 한다.","src":"한능검 제67회"},{"answer":"X","text":"조선 후기에는 상평통보의 유통이 크게 늘면서 시중에 동전이 넘쳐나 화폐 가치가 떨어지는 전황 현상이 나타났다.","exp":"전황의 뜻이 틀렸다. 전황은 동전이 넘쳐난 것이 아니라 지주·상인이 동전을 쌓아 두어 시중에 돈이 부족해진 현상이다. 상평통보가 전국적으로 유통된 사실 자체는 옳다."}],"tb":[],"wi":[]},{"p":"PART 6. 조선 후기 문화·예술과 종교","q":[{"answer":"O","text":"천주교 신자였던 황사영은 신유박해의 실상과 외국의 개입을 요청하는 내용을 담은 백서를 지어 베이징의 천주교 주교에게 전하려다 발각되었다.","exp":"황사영 백서 사건은 신유박해(1801)의 여파 속에서 일어났다. 박해의 실상을 알리고 외세의 도움을 청하려 한 이 사건은 오히려 천주교에 대한 탄압을 강화시키는 계기가 되었다.","src":"한능검 제67회"},{"answer":"X","text":"천주교 신자였던 황사영은 신유박해의 실상을 알리는 백서를 지어 일본 에도 막부에 전하려다 발각되어 처형되었다.","exp":"전하려 한 대상이 틀렸다. 황사영은 백서를 일본 에도 막부가 아니라 베이징의 천주교 주교에게 전하려 하였다. 이 사건은 순조 때 신유박해와 맞물려 일어났다."}],"tb":[{"k":"p","t":"신유박해(1801) 때에는 천주교 신자 황사영이 박해의 실상과 외국의 개입 요청을 담은 백서를 베이징의 천주교 주교에게 전하려다 발각되는 사건도 일어났다(황사영 백서 사건). 이 사건은 오히려 천주교에 대한 탄압을 강화시키는 계기가 되었다."}],"wi":["📝 \"황사영이 백서를 일본 에도 막부에 전하려 함\" → ❌ 베이징 천주당(주교)에 전하려다 발각 — 신유박해(1801) 때의 사건"]}];
