    var TAGS = [{"n":"육의전을 제외한 시전 상인의 금난전권을 폐지하고 자유로운","l":"한능검 제65회"},{"n":"국가에서 필요한 물품을 조달하는 공인이 등장하여 활동하였다","l":"한능검 제65회"}];
