    var ADDS = [{"p":"PART 3. 수취 체제 개편·경제 변화","q":[{"answer":"O","text":"조선 후기에는 고추와 담배 등을 상품 작물로 재배하여 장시에 내다 파는 농민의 모습을 흔히 볼 수 있었다.","exp":"맞다. 조선 후기에는 시장에 내다 팔기 위한 상품 작물 재배가 활발해져 담배·인삼·목화와 함께 고추도 널리 재배되었다. 설점수세제에 따른 광산 개발과 더불어 농업의 상업화가 진전된 조선 후기 경제의 모습이다.","src":"한능검 제64회"},{"answer":"X","text":"조선 후기에는 고추와 담배 등을 상품 작물로 재배하는 농민과 함께, 벽란도에서 송·아라비아 상인과 교역하는 모습도 볼 수 있었다.","exp":"틀리다. 상품 작물을 재배하는 농민은 조선 후기의 모습이 맞지만, 벽란도에서 송·아라비아 상인과 교역한 것은 고려 시대의 일이다. 시대가 다른 두 사실을 한 장면에 섞은 함정이다."}],"tb":[],"wi":[]},{"p":"PART 6. 조선 후기 문화·예술과 종교","q":[{"answer":"X","text":"조선 후기에는 진경 산수화가 그려지고 판소리가 유행하는 한편, 새로운 역법으로 수시력이 도입되어 사용되었다.","exp":"틀리다. 진경 산수화·판소리는 조선 후기가 맞지만, 수시력은 고려 충선왕 때 도입된 원의 역법이다. 조선 후기에 새로 채택된 역법은 청에서 들여온 시헌력(김육)이므로 역법이 뒤바뀌었다.","src":"한능검 제64회"},{"answer":"O","text":"조선 후기에는 진경 산수화가 그려지고 판소리가 유행하는 한편, 청에서 들여온 시헌력이 새로운 역법으로 채택되어 사용되었다.","exp":"맞다. 시헌력은 청을 통해 들어온 서양식 역법으로 김육 등의 노력으로 조선 후기에 채택되었다. 원의 역법인 수시력이 고려 충선왕 때 도입된 것과 시기를 구분해야 한다."}],"tb":[{"k":"p","t":"역법에서는 청을 통해 들어온 서양식 역법인 시헌력이 김육 등의 노력으로 조선 후기에 채택되었다. 원의 수시력이 고려 충선왕 때 도입된 것과 시기를 구분해야 한다."}],"wi":["수시력 = 고려 충선왕 도입(원 역법) / 조선 후기 새 역법은 시헌력(김육) — 수시력을 조선 후기 역법으로 쓰면 ❌"]},{"p":"PART 5. 성리학의 변화와 실학","q":[{"answer":"O","text":"정약용은 서양 기술을 소개한 기기도설을 참고하여 거중기를 설계하였고, 이를 수원 화성 축조에 활용하였다.","exp":"맞다. 정약용은 기기도설을 참고해 거중기를 만들어 수원 화성 공사의 기간과 비용을 크게 줄였다. 강진 유배 중 목민심서·경세유표·흠흠신서를 저술한 실학의 집대성자로, 열하일기의 박지원과 구분해 기억한다.","src":"한능검 제64회"},{"answer":"X","text":"정약용은 강진 유배 중 목민심서와 경세유표를 저술하였으며, 곤여만국전도를 참고하여 거중기를 설계하였다.","exp":"틀리다. 강진 유배와 목민심서·경세유표 저술은 정약용이 맞지만, 거중기를 설계할 때 참고한 것은 곤여만국전도가 아니라 기기도설이다. 곤여만국전도는 서양식 세계 지도로 성격이 전혀 다르다."}],"tb":[],"wi":[]}];
