    var ADDS = [{"p":"PART 1. 통치 체제 개편·붕당 정치의 전개","q":[{"answer":"O","text":"선조 때 동인과 서인으로 붕당이 나뉜 뒤, 광해군을 뒷받침하던 북인은 인조반정으로 정권에서 몰락하고 서인이 정국을 주도하게 되었다.","exp":"인조반정(1623)으로 광해군과 그를 지지하던 북인이 축출되고 서인이 집권하였다. 이후 서인은 남인과 함께 예송을 벌였고, 북인은 정치 무대에서 사실상 사라졌다.","src":"한능검 제63회"},{"answer":"X","text":"선조 때 동인과 서인으로 붕당이 나뉜 뒤, 광해군을 뒷받침하던 북인은 인조반정으로 정권에서 몰락하고 이후 남인이 정국을 주도하게 되었다.","exp":"틀렸다. 인조반정으로 북인이 몰락한 것은 맞으나, 반정을 주도해 정국을 장악한 세력은 남인이 아니라 서인이다. 남인은 이후 서인과 예송·환국에서 경쟁한 붕당이다."}],"tb":[],"wi":[]},{"p":"PART 1. 통치 체제 개편·붕당 정치의 전개","q":[{"answer":"O","text":"비변사는 흥선 대원군이 집권한 시기에 이르러 혁파되고, 그 기능을 대신하여 의정부와 삼군부가 부활되었다.","exp":"임진왜란 이후 최고 기구가 된 비변사는 세도 정치의 기반이 되었다가 흥선 대원군 집권기에 혁파되었다. 대원군은 의정부(행정)와 삼군부(군사)를 부활시켜 왕권을 강화하였다.","src":"한능검 제63회"},{"answer":"X","text":"비변사는 흥선 대원군이 집권한 시기에 이르러 혁파되고, 그 기능을 대신하여 통리기무아문이 최고 기구로 설치되었다.","exp":"틀렸다. 비변사 혁파는 맞지만 그 기능을 대신한 것은 의정부와 삼군부의 부활이다. 통리기무아문은 1880년 개화 정책을 총괄하기 위해 설치된 기구로 시기와 성격이 다르다."}],"tb":[],"wi":[]},{"p":"PART 1. 통치 체제 개편·붕당 정치의 전개","q":[{"answer":"O","text":"정묘호란 때 정봉수는 용골산성에서 고립된 성을 지키며 후금군의 공격을 두 차례 막아 내는 등 충성과 용맹을 떨쳤다.","exp":"정묘호란(1627)은 후금의 침입으로 일어났고, 정봉수는 용골산성에서 의병을 이끌고 항전하였다. 조선이 후금과 형제 관계를 맺으며 마무리된 점과 함께 기억한다.","src":"한능검 제63회"},{"answer":"X","text":"정묘호란 때 정봉수는 용골산성에서 고립된 성을 지키며 청군의 대규모 침입을 두 차례 막아 내는 등 충성과 용맹을 떨쳤다.","exp":"틀렸다. 정봉수의 용골산성 항전은 맞지만, 정묘호란(1627)의 침입 세력은 청이 아니라 후금이다. 후금이 국호를 청으로 고친 뒤 일으킨 전쟁은 병자호란(1636)이다."}],"tb":[],"wi":["정묘호란(1627) = 후금 침입·정봉수 용골산성 항전 ⭕ → 침입 세력을 청으로 쓰면 ❌ (청 침입은 병자호란 1636)"]},{"p":"PART 3. 수취 체제 개편·경제 변화","q":[{"answer":"O","text":"조선 후기에는 인삼, 담배 등이 상품 작물로 재배되어 시장에 내다 팔렸다.","exp":"조선 후기에는 시장 판매를 목적으로 한 인삼·담배·목화 등 상품 작물 재배가 활발해졌다. 이앙법 확대에 따른 광작과 함께 농업의 상업화가 진전된 모습이다.","src":"한능검 제63회"},{"answer":"X","text":"조선 후기에는 인삼, 담배 등이 상품 작물로 재배되었으나, 이러한 작물은 오직 관청에서만 재배하여 민간의 매매가 금지되었다.","exp":"틀렸다. 인삼·담배가 상품 작물로 재배된 것은 맞지만, 이는 관청 독점이 아니라 민간에서 시장 판매를 위해 자유롭게 재배·거래되었다. 상품 화폐 경제 발달을 보여 주는 현상이다."}],"tb":[],"wi":[]},{"p":"PART 3. 수취 체제 개편·경제 변화","q":[{"answer":"O","text":"부산 동래에서는 내상이 왜관을 중심으로 일본과의 무역 활동을 전개하였다.","exp":"내상은 동래(부산)를 근거지로 왜관을 통한 대일본 무역을 담당한 사상이다. 대청 무역을 주도한 의주의 만상·개성의 송상과 무역 상대를 구분해 기억한다.","src":"한능검 제63회"},{"answer":"X","text":"부산 동래에서는 내상이 왜관을 중심으로 활발히 무역 활동을 전개하였으며, 이들은 개성에 송방이라는 지점을 두고 전국의 상권을 장악하였다.","exp":"틀렸다. 내상이 동래에서 대일본 무역을 한 것은 맞지만, 송방이라는 지점을 전국에 두고 상권을 장악한 상인은 개성의 송상이다. 내상과 송상의 활동을 뒤섞은 서술이다."}],"tb":[],"wi":[]},{"p":"PART 6. 조선 후기 문화·예술과 종교","q":[],"tb":[{"k":"p","t":"천주교 박해는 진산 사건(1791, 윤지충·권상연이 신주를 불태우고 제사를 폐한 일)에서 표면화되어, 순조 즉위 초 신유박해(1801)로 확대되었다. 이때 황사영은 박해의 실상을 베이징 주교에게 알리고 외국 군대의 출병을 요청하는 백서를 작성하려다 발각되었으며, 이후 기해박해(1839)·병인박해(1866)로 탄압이 거듭되었다."}],"wi":["황사영 백서 = 신유박해(1801) 때의 사건 ⭕ → 기해박해·병인박해와 연결하면 ❌ (시기 다름)"]}];
