    var ADDS = [{"part":"PART 1. 통치 체제 개편·붕당 정치의 전개","answer":"X","text":"조선은 광해군 때 기유약조를 체결하여 임진왜란으로 끊어졌던 국교를 회복하고 여진과의 무역을 재개하였다.","exp":"무역 상대가 틀렸다. 기유약조는 여진이 아니라 일본(쓰시마)과 맺은 조약으로, 임진왜란으로 끊긴 국교를 회복하고 제한된 범위의 무역을 허용한 것이다. 여진에 대해서는 앞서 태종 때 경성과 경원에 무역소를 두어 회유하였다.","src":"한능검 제62회"},{"part":"PART 6. 조선 후기 문화·예술과 종교","answer":"O","text":"정조가 정치적 이상을 담아 축조한 수원 화성은 행궁과 서장대를 두고 포루, 공심돈 등의 방어 시설을 갖추었다.","exp":"수원 화성은 정조가 행차할 때 머물던 행궁과 장용영 군사를 지휘하던 서장대를 갖추고, 성벽에 포루·공심돈 같은 새로운 방어 시설을 둔 계획도시였다. 정약용이 고안한 거중기를 활용해 공사 기간과 비용을 크게 줄인 점도 함께 기억한다.","src":"한능검 제62회"},{"part":"PART 6. 조선 후기 문화·예술과 종교","answer":"X","text":"정조가 정치적 이상을 담아 축조한 수원 화성은 행궁과 서장대를 갖추었으며, 당백전을 발행하여 그 건설 비용에 충당하였다.","exp":"끝부분이 틀렸다. 당백전은 흥선 대원군이 경복궁 중건 비용을 마련하려고 발행한 고액 화폐로 수원 화성 축조와는 관계가 없다. 화성은 거중기 등 새로운 기술을 활용해 비용과 기간을 줄이며 지었다.","src":"한능검 제62회"},{"part":"PART 5. 성리학의 변화와 실학","answer":"O","text":"의산문답을 지은 홍대용과 허생전을 지은 박지원은 모두 연행사의 일원으로 청에 다녀와 연행록을 남겼다.","exp":"두 사람은 사신단인 연행사를 따라 청에 다녀온 뒤 그 견문을 기록으로 남기고 청의 발달한 문물을 받아들이자고 주장한 북학파였다. 일본에 파견된 통신사와 대상국을 구분해 기억한다.","src":"한능검 제62회"},{"part":"PART 5. 성리학의 변화와 실학","answer":"X","text":"홍대용과 박지원은 연행사의 일원으로 청에 다녀온 뒤, 농민 생활의 안정을 위하여 화폐 사용을 반대하였다.","exp":"끝부분이 틀렸다. 박지원은 오히려 수레와 선박의 이용, 화폐 유통의 필요성을 강조하였고 홍대용도 상공업 진흥을 주장하였다. 화폐가 고리대와 사치를 부추긴다며 그 사용에 반대한 인물은 이익이다.","src":"한능검 제62회"},{"part":"PART 6. 조선 후기 문화·예술과 종교","answer":"O","text":"조선 후기에는 책과 도자기, 문방구 등을 그린 책가도가 유행하고 다양한 주제의 민화가 왕실과 사대부뿐만 아니라 서민들에게도 인기를 끌었다.","exp":"조선 후기에는 서민의 경제력과 의식이 성장하면서 민화가 널리 퍼졌고 책가도가 유행하였다. 판소리·탈춤·한글 소설·사설시조와 함께 조선 후기 서민 문화로 묶어 기억하고, 벽란도에서 송 상인이 오가는 모습은 고려 시대의 것이므로 같은 시기의 장면에 섞지 않아야 한다.","src":"한능검 제62회"},{"part":"PART 6. 조선 후기 문화·예술과 종교","answer":"O","text":"조선 시대 왕실이나 국가의 큰 행사를 글과 그림으로 기록한 의궤는 왕의 열람을 위한 어람용이 따로 제작되었으며, 그 일부가 병인양요 당시 프랑스군에게 약탈되었다.","exp":"의궤는 하나의 행사를 주제로 그 전 과정을 글과 그림으로 정리한 기록물로, 왕이 보는 어람용과 관청에 나누어 두는 분상용으로 구분해 만들었다. 강화도에 보관되던 의궤 일부는 병인양요 때 프랑스군에게 약탈되었다.","src":"한능검 제62회"},{"part":"PART 6. 조선 후기 문화·예술과 종교","answer":"X","text":"조선 시대 왕실이나 국가의 큰 행사를 글과 그림으로 기록한 의궤는 사초와 시정기를 바탕으로 연대순의 편년체로 편찬되었다.","exp":"뒷부분이 틀렸다. 사초와 시정기를 바탕으로 연대순의 편년체로 편찬된 것은 조선왕조실록이다. 의궤는 행사별로 그 전 과정을 글과 그림으로 정리한 기록물이며 왕이 볼 어람용이 따로 제작되었다.","src":"한능검 제62회"}];
